mapper.select:
select id, user_id, username, method_name, operation, duration_ms,
       status, target_type, target_id, error_code, created_at
from operation_log


        and user_id = #{userId}


        and status = #{status}


        and created_at >= #{startTime}


        and created_at < #{endTime}


order by created_at desc, id desc
